#!/usr/bin/env python3
"""One Gate-owned J07 semantic canary against the frozen managed Runtime.

This is recovery-03's thin assertion layer with its accepted evidence ownership
boundary retained. Opt81 owns strict Go-style MySQL DSN parsing and lazy PyMySQL
connection; this harness supplies no connector or DSN parsing code.
"""

import datetime
import decimal
import hashlib
import importlib.util
import json
import os
import sys
import time
import urllib.parse


PROJECT_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", ".."))
SESSION_ROOT = os.path.join(PROJECT_ROOT, ".domainry", "development", "m1-opt82-semantic-canary-06")
EVIDENCE_PATH = os.path.join(SESSION_ROOT, "semantic-canary-result.json")
CORE_PATH = "/Users/tiger/.codex/isolated/opt82/skills/domainry-builder-v1/assets/acceptance-harness-core.py"
RUNTIME_STATE_PATH = os.path.join(PROJECT_ROOT, ".domainry", "builder", "runtime", "runtime-process.json")
SOURCE_RELATIVE = ".domainry/development/m1-opt82-semantic-canary-06/semantic_canary.py"


def load_core():
    spec = importlib.util.spec_from_file_location("domainry_acceptance_harness_core", CORE_PATH)
    if spec is None or spec.loader is None:
        raise RuntimeError("canonical acceptance harness core is unavailable")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


core = load_core()


def sha256_json(value):
    raw = json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def source_sha256():
    with open(__file__, "rb") as handle:
        return hashlib.sha256(handle.read()).hexdigest()


def records_from(exchange):
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=False)
    candidates = exchange.body_list
    if candidates is None:
        body = exchange.body or {}
        candidates = body.get("records") or body.get("items") or body.get("results")
        if candidates is None and isinstance(body.get("data"), list):
            candidates = body["data"]
        if candidates is None and isinstance(body.get("data"), dict):
            nested = body["data"]
            candidates = nested.get("records") or nested.get("items") or nested.get("results")
    if candidates is None:
        candidates = []
    if not isinstance(candidates, list) or any(not isinstance(item, dict) for item in candidates):
        raise core.HarnessError("Runtime record list has an unsupported shape")
    return candidates


def record_from(exchange):
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=True)
    body = exchange.body or {}
    nested_record = None
    if isinstance(body.get("data"), dict):
        nested_record = body["data"].get("record")
    for candidate in (body, body.get("record"), body.get("data"), nested_record):
        if isinstance(candidate, dict) and isinstance(candidate.get("id"), str) and isinstance(candidate.get("data"), dict):
            return candidate
    raise core.HarnessError("Runtime detail response has no canonical record id/data")


def action_definitions(exchange):
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=True)
    candidates = exchange.body_list
    if candidates is None:
        body = exchange.body or {}
        candidates = body.get("actions") or body.get("items") or body.get("results") or body.get("data")
    if isinstance(candidates, dict):
        candidates = candidates.get("actions") or candidates.get("items")
    if not isinstance(candidates, list):
        raise core.HarnessError("Runtime action list has an unsupported shape")
    return candidates


def output_from(exchange):
    body = exchange.body or {}
    candidates = [body]
    for key in ("data", "result", "output"):
        if isinstance(body.get(key), dict):
            candidates.append(body[key])
    for candidate in candidates:
        keys = ("approval_id", "lead_id", "customer_id")
        if all(isinstance(candidate.get(key), str) and candidate.get(key) for key in keys):
            return {key: candidate[key] for key in keys}
    raise core.HarnessError("positive Action result lacks non-empty approval/lead/customer identities")


def relation_id(value):
    if isinstance(value, str) and value:
        return value
    if isinstance(value, dict):
        for key in ("id", "record_id", "value"):
            if isinstance(value.get(key), str) and value.get(key):
                return value[key]
    raise core.HarnessError("Runtime relation value has no opaque target identity")


def stable_error(exchange):
    body = exchange.body or {}
    value = body.get("code") or body.get("error")
    if isinstance(value, dict):
        value = value.get("code")
    if not value and isinstance(body.get("details"), dict):
        value = body["details"].get("code")
    return str(value or exchange.error_code or "")


def request(runtime, method, path, session=None, body=None, idempotency_key=""):
    return runtime.request(method, path, session=session, body=body, idempotency_key=idempotency_key)


def list_records(runtime, session, object_key):
    path = "/objects/%s/records?page=1&page_size=200" % urllib.parse.quote(object_key, safe="")
    return records_from(request(runtime, "GET", path, session=session))


def get_record(runtime, session, object_key, record_id):
    path = "/objects/%s/records/%s" % (
        urllib.parse.quote(object_key, safe=""), urllib.parse.quote(record_id, safe=""))
    return record_from(request(runtime, "GET", path, session=session))



def resolve_customer_storage(database):
    """Resolve one physical customer relation using parameterized metadata SELECTs."""
    rows = database.query(
        "SELECT table_name, column_name FROM information_schema.columns "
        "WHERE table_schema=DATABASE() AND column_name IN (%s,%s,%s) "
        "ORDER BY table_name, ordinal_position",
        ("id", "source_lead_id", "company_name"),
    )
    columns_by_table = {}
    for row in rows:
        table = str(row.get("table_name") or "")
        column = str(row.get("column_name") or "")
        if table and column:
            columns_by_table.setdefault(table, set()).add(column)
    candidates = [
        table for table, columns in columns_by_table.items()
        if {"id", "source_lead_id", "company_name"}.issubset(columns)
    ]
    exact = [table for table in candidates if table.lower() == "customer"]
    if len(exact) == 1:
        selected = exact[0]
    elif len(candidates) == 1:
        selected = candidates[0]
    else:
        raise core.HarnessError(
            "canonical MySQL cohort did not resolve exactly one customer persistence relation")
    return {
        "table": selected,
        "id_column": "id",
        "lead_column": "source_lead_id",
        "company_column": "company_name",
    }


def normalized_database_value(value):
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, decimal.Decimal):
        return format(value, "f")
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, bytes):
        return {"bytes": len(value), "sha256": hashlib.sha256(value).hexdigest()}
    if isinstance(value, dict):
        return {str(key): normalized_database_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [normalized_database_value(item) for item in value]
    return str(value)


def database_customer_rows(database, storage, lead_id):
    relation = database.relation(storage["table"])
    lead_column = database.identifier(storage["lead_column"])
    id_column = database.identifier(storage["id_column"])
    sql = "SELECT * FROM %s WHERE %s=%s ORDER BY %s" % (
        relation, lead_column, database.placeholder(), id_column)
    rows = database.query(sql, (lead_id,))
    return [
        {str(key): normalized_database_value(value) for key, value in row.items()}
        for row in rows
    ]


def durable_closure(runtime, director, database, storage, approval_id, lead_id):
    approval = get_record(runtime, director, "conversion_approval", approval_id)
    lead = get_record(runtime, director, "lead", lead_id)
    customers = database_customer_rows(database, storage, lead_id)
    closure = {
        "approval": core.durable_record_snapshot(approval),
        "lead": core.durable_record_snapshot(lead),
        "customer_database_rows": customers,
    }
    return closure, sha256_json(closure)


def principal_evidence(session):
    context = session.get("principal_context") or {}
    safe_contexts = []
    for item in context.get("request_contexts") or []:
        safe = {}
        for key in (
            "subject_kind", "user_id", "workspace_id", "surface_key", "business_profile_key",
            "business_profile_id", "workforce_profile_id", "organization_id", "organization_unit_id",
        ):
            if key in item and item[key] not in (None, ""):
                safe[key] = item[key]
        headers = item.get("canonical_request_headers") or {}
        safe["canonical_header_names"] = sorted(headers)
        safe["canonical_header_values_sha256"] = sha256_json(headers)
        safe_contexts.append(safe)
    return {
        "contract_version": context.get("contract_version"),
        "known": context.get("known"),
        "user_id": context.get("user_id"),
        "workspace_id": context.get("workspace_id"),
        "role_keys": sorted(context.get("role_keys") or []),
        "request_contexts": safe_contexts,
    }


def workforce_context(sessions, user_id):
    authenticated = sessions.session(user_id)
    contexts = [
        item for item in authenticated["principal_context"].get("request_contexts") or []
        if item.get("subject_kind") == "workforce"
    ]
    if len(contexts) != 1:
        raise core.HarnessError(
            "authenticated principal-context did not return exactly one workforce context")
    workforce_profile_id = contexts[0].get("workforce_profile_id")
    if not isinstance(workforce_profile_id, str) or not workforce_profile_id:
        raise core.HarnessError(
            "authenticated workforce context lacks a formal workforce_profile_id selector")
    return sessions.context(
        user_id, "workforce", workforce_profile_id=workforce_profile_id)


def notification_nodes(value):
    nodes = []
    if isinstance(value, dict):
        nodes.append(value)
        for child in value.values():
            nodes.extend(notification_nodes(child))
    elif isinstance(value, list):
        for child in value:
            nodes.extend(notification_nodes(child))
    return nodes


def inbox_matches(runtime, requester, approval_id):
    path = "/business/notifications?surface=business_workspace&page=1&page_size=200"
    exchange = request(runtime, "GET", path, session=requester)
    core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=False)
    body = exchange.body if exchange.body is not None else exchange.body_list
    matches = []
    for node in notification_nodes(body):
        rendered = json.dumps(node, sort_keys=True, separators=(",", ":"))
        if approval_id in rendered and (
                "crm.conversion_approved" in rendered or "conversion_approved" in rendered):
            matches.append(node)
    identities = []
    for node in matches:
        for key in ("id", "notification_id", "inbox_item_id"):
            if isinstance(node.get(key), str) and node.get(key):
                identities.append(node[key])
                break
    return exchange, sorted(set(identities)), len(matches)


def write_evidence(document, sensitive):
    raw = json.dumps(document, indent=2, sort_keys=True).encode("utf-8")
    if any(secret and secret.encode("utf-8") in raw for secret in sensitive):
        raise RuntimeError("refusing to persist a live credential, DSN, or session secret")
    os.makedirs(os.path.dirname(EVIDENCE_PATH), exist_ok=True)
    temporary = EVIDENCE_PATH + ".tmp"
    with open(temporary, "wb") as handle:
        handle.write(raw)
    os.chmod(temporary, 0o644)
    os.replace(temporary, EVIDENCE_PATH)


def main():
    started_wall = time.time()
    started_active = time.monotonic()
    checkpoint = "runtime_and_database_binding"
    ordered_assertions = [
        "runtime_and_database_binding",
        "formal_sessions_and_workforce_contexts",
        "action_and_pending_target_resolution",
        "customer_nonexistence",
        "requester_denied_action_unchanged",
        "director_positive_action_and_durable_change",
        "requester_inbox",
        "idempotent_replay_unchanged",
        "second_director_terminal_conflict_unchanged",
    ]
    evidence = {
        "contract_version": "domainry-semantic-canary-evidence-v1",
        "session_id": "m1-opt82-semantic-canary-06",
        "journey": "J07",
        "requirements": ["R07", "R08", "R09", "R10", "R13"],
        "action": "conversion_approval.approve_conversion",
        "producer": {
            "source": SOURCE_RELATIVE,
            "source_sha256": source_sha256(),
            "canonical_core": CORE_PATH,
            "database_path": "AcceptanceDatabase.from_runtime_state",
            "database_connector": "core_owned_lazy_pymysql_no_callback",
        },
        "state": "failed",
        "failure_inventory": [],
        "blocked_assertions": [],
    }
    sessions = None
    database = None
    try:
        state = core.load_json(RUNTIME_STATE_PATH)
        if state.get("database_driver") != "mysql":
            raise core.HarnessError("managed Runtime cohort is not MySQL")
        if state.get("state") != "running" or state.get("healthy") is not True:
            raise core.HarnessError("managed Runtime receipt is not healthy")
        address = state.get("address")
        api_base_url = state.get("api_base_url")
        parsed_runtime = urllib.parse.urlsplit(str(api_base_url or ""))
        if not isinstance(address, str) or not address or \
                parsed_runtime.scheme != "http" or parsed_runtime.netloc != address:
            raise core.HarnessError("managed Runtime receipt address and API base URL do not match")
        runtime = core.Runtime(api_base_url)
        database = core.AcceptanceDatabase.from_runtime_state(PROJECT_ROOT, state)
        storage = resolve_customer_storage(database)
        evidence["runtime_identity"] = {
            "address": state.get("address"),
            "database_driver": state.get("database_driver"),
            "database_identity_sha256": state.get("database_identity_sha256"),
            "database_dsn_identity_sha256": state.get("database_dsn_identity_sha256"),
            "runtime_manifest_sha256": state.get("runtime_manifest_sha256"),
            "bundle_manifest_sha256": state.get("bundle_manifest_sha256"),
            "binary_sha256": state.get("binary_sha256"),
            "package_receipt_sha256": state.get("package_receipt_sha256"),
            "verification_receipt_sha256": state.get("verification_receipt_sha256"),
            "finalization_receipt_sha256": state.get("finalization_receipt_sha256"),
            "project_source_tree_sha256": state.get("project_source_tree_sha256"),
            "origin": state.get("origin"),
        }
        evidence["database_evidence"] = {
            "cohort_verified_by_canonical_core": True,
            "driver": database.driver,
            "customer_relation": storage["table"],
            "query_mode": "parameterized_read_only_select",
        }

        checkpoint = "formal_sessions_and_workforce_contexts"
        sessions = core.Sessions(
            runtime, PROJECT_ROOT, workspace_id="default",
            database_identity_sha256=state.get("database_identity_sha256", ""))
        requester = workforce_context(sessions, "east_rep_primary")
        director = workforce_context(sessions, "sales_director_primary")
        competing_director = workforce_context(sessions, "sales_director_secondary")
        evidence["formal_principals"] = {
            "requester": principal_evidence(requester),
            "director": principal_evidence(director),
            "competing_director": principal_evidence(competing_director),
        }

        checkpoint = "action_and_pending_target_resolution"
        action_list = request(
            runtime, "GET", "/objects/conversion_approval/actions", session=director)
        definitions = action_definitions(action_list)
        selected = [
            item for item in definitions
            if item.get("key") == "conversion_approval.approve_conversion"]
        if len(selected) != 1 or selected[0].get("kind") != "record_operation":
            raise core.HarnessError(
                "published Runtime Action list did not resolve one record_operation approval Action")
        action_key = selected[0]["key"]

        pending = []
        for approval in list_records(runtime, director, "conversion_approval"):
            data = approval.get("data") or {}
            submitted = str(data.get("submitted_amount"))
            if data.get("status") == "pending" and data.get("requester_id") == "east_rep_primary" and \
                    submitted in ("100000", "100000.0", "100000.00"):
                pending.append(approval)
        if len(pending) != 1:
            raise core.HarnessError(
                "fresh setup did not resolve exactly one pending threshold approval")
        approval_before = pending[0]
        approval_id = approval_before["id"]
        lead_id = relation_id(approval_before["data"].get("lead_id"))
        lead_before = get_record(runtime, director, "lead", lead_id)
        if lead_before["data"].get("status") != "qualified" or not lead_before["data"].get("company_name"):
            raise core.HarnessError(
                "resolved approval does not reference one non-empty qualified lead")

        checkpoint = "customer_nonexistence"
        before_closure, before_sha = durable_closure(
            runtime, director, database, storage, approval_id, lead_id)
        if before_closure["customer_database_rows"]:
            raise core.HarnessError("fresh pending approval already has a persisted customer")

        action_path = "/objects/%s/records/%s/actions/%s" % (
            urllib.parse.quote("conversion_approval", safe=""),
            urllib.parse.quote(approval_id, safe=""),
            urllib.parse.quote(action_key, safe=""),
        )
        checkpoint = "requester_denied_action_unchanged"
        denied_key = core.new_probe_token("j07-denied")
        denied = request(
            runtime, "POST", action_path, session=requester,
            body={"data": {"request_id": denied_key}}, idempotency_key=denied_key)
        denied.error_code = stable_error(denied)
        _, after_denied_sha = durable_closure(
            runtime, director, database, storage, approval_id, lead_id)
        core.ReasonOracle.rejection(
            denied, statuses=(403,), error_code="backend.action.permission_denied",
            before_sha256=before_sha, after_sha256=after_denied_sha)

        checkpoint = "director_positive_action_and_durable_change"
        command_key = core.new_probe_token("j07-approve")
        positive = request(
            runtime, "POST", action_path, session=director,
            body={"data": {"request_id": command_key}}, idempotency_key=command_key)
        core.ReasonOracle.success(positive, statuses=(200, 201), require_non_empty=True)
        positive_output = output_from(positive)
        if positive_output["approval_id"] != approval_id or positive_output["lead_id"] != lead_id:
            raise core.HarnessError(
                "positive Action output does not name the resolved target identities")

        positive_closure, positive_sha = durable_closure(
            runtime, director, database, storage, approval_id, lead_id)
        core.ReasonOracle.state(before_sha, positive_sha, changed=True)
        approval_after = positive_closure["approval"]
        lead_after = positive_closure["lead"]
        customer_rows = positive_closure["customer_database_rows"]
        if approval_after["data"].get("status") != "approved":
            raise core.HarnessError("director approval read-back is not approved")
        if lead_after["data"].get("status") != "converted":
            raise core.HarnessError("director lead read-back is not converted")
        if len(customer_rows) != 1:
            raise core.HarnessError(
                "canonical MySQL closure does not contain exactly one linked customer")
        customer_row = customer_rows[0]
        if str(customer_row.get(storage["id_column"]) or "") != positive_output["customer_id"]:
            raise core.HarnessError(
                "persisted customer identity differs from the positive Action output")
        if str(customer_row.get(storage["lead_column"]) or "") != lead_id:
            raise core.HarnessError("persisted customer references the wrong source lead")
        if not str(customer_row.get(storage["company_column"]) or "").strip():
            raise core.HarnessError("persisted customer lacks copied non-empty company facts")
        customer_row_sha = sha256_json(customer_row)

        checkpoint = "requester_inbox"
        inbox_after, inbox_ids_after, inbox_count_after = inbox_matches(
            runtime, requester, approval_id)
        if inbox_count_after < 1:
            raise core.HarnessError(
                "requester-visible Business Inbox has no approval-result item")

        checkpoint = "idempotent_replay_unchanged"
        replay = request(
            runtime, "POST", action_path, session=director,
            body={"data": {"request_id": command_key}}, idempotency_key=command_key)
        core.ReasonOracle.success(replay, statuses=(200, 201), require_non_empty=True)
        replay_output = output_from(replay)
        _, replay_sha = durable_closure(
            runtime, director, database, storage, approval_id, lead_id)
        core.ReasonOracle.state(positive_sha, replay_sha, changed=False)
        if replay_output != positive_output:
            raise core.HarnessError(
                "idempotent replay did not return the original target identities")
        inbox_replay, inbox_ids_replay, inbox_count_replay = inbox_matches(
            runtime, requester, approval_id)
        if inbox_count_replay != inbox_count_after or inbox_ids_replay != inbox_ids_after:
            raise core.HarnessError(
                "idempotent replay duplicated requester-visible Inbox state")

        checkpoint = "second_director_terminal_conflict_unchanged"
        conflict_key = core.new_probe_token("j07-conflict")
        conflict = request(
            runtime, "POST", action_path, session=competing_director,
            body={"data": {"request_id": conflict_key}}, idempotency_key=conflict_key)
        conflict.error_code = stable_error(conflict)
        _, conflict_sha = durable_closure(
            runtime, director, database, storage, approval_id, lead_id)
        core.ReasonOracle.rejection(
            conflict, statuses=(409, 422),
            error_code="conversion_approval.approve_conversion.invalid_state",
            before_sha256=replay_sha, after_sha256=conflict_sha)

        evidence.update({
            "state": "passed",
            "opaque_identities": {
                "action_key_from_runtime": action_key,
                "approval_id": approval_id,
                "lead_id": lead_id,
                "customer_id": positive_output["customer_id"],
                "inbox_item_ids": inbox_ids_after,
            },
            "denied": {
                "status": denied.status,
                "error_code": denied.error_code,
                "request_id": denied.request_id,
                "before_sha256": before_sha,
                "after_sha256": after_denied_sha,
                "unchanged": before_sha == after_denied_sha,
                "closure_includes_database_customer_rows": True,
            },
            "positive": {
                "status": positive.status,
                "request_id": positive.request_id,
                "output": positive_output,
                "before_sha256": before_sha,
                "after_sha256": positive_sha,
                "approval_status": approval_after["data"].get("status"),
                "lead_status": lead_after["data"].get("status"),
                "database_customer_count_for_lead": len(customer_rows),
                "database_customer_row_sha256": customer_row_sha,
                "customer_company_non_empty": bool(
                    str(customer_row.get(storage["company_column"]) or "").strip()),
                "requester_inbox_matches": inbox_count_after,
                "requester_inbox_http_status": inbox_after.status,
                "closure_includes_database_customer_rows": True,
            },
            "replay": {
                "status": replay.status,
                "request_id": replay.request_id,
                "runtime_replayed_header": replay.replayed,
                "same_output": replay_output == positive_output,
                "before_sha256": positive_sha,
                "replay_sha256": replay_sha,
                "unchanged": positive_sha == replay_sha,
                "requester_inbox_matches": inbox_count_replay,
                "requester_inbox_http_status": inbox_replay.status,
                "closure_includes_database_customer_rows": True,
            },
            "conflict": {
                "status": conflict.status,
                "error_code": conflict.error_code,
                "request_id": conflict.request_id,
                "before_sha256": replay_sha,
                "after_sha256": conflict_sha,
                "unchanged": replay_sha == conflict_sha,
                "closure_includes_database_customer_rows": True,
            },
        })
    except Exception as error:
        evidence["failure_inventory"].append({
            "owner": "harness_or_runtime_or_project",
            "code": error.__class__.__name__,
            "checkpoint": checkpoint,
            "reason": str(error)[:500],
        })
        if checkpoint in ordered_assertions:
            failed_index = ordered_assertions.index(checkpoint)
            evidence["blocked_assertions"] = ordered_assertions[failed_index + 1:]
    finally:
        if database is not None:
            try:
                database.connection.close()
            except Exception:
                evidence["failure_inventory"].append({
                    "owner": "harness",
                    "code": "database_close_failed",
                    "checkpoint": "cleanup",
                    "reason": "read-only acceptance database connection did not close cleanly",
                })
                evidence["state"] = "failed"
        active_duration = time.monotonic() - started_active
        evidence["started_at_epoch"] = int(started_wall)
        evidence["completed_at_epoch"] = int(time.time())
        evidence["pure_active_duration_seconds"] = round(active_duration, 6)
        sensitive = [] if sessions is None else list(sessions.sensitive)
        if database is not None:
            sensitive.extend(database.sensitive)
        try:
            write_evidence(evidence, sensitive)
        except Exception:
            evidence = {
